-- Run after admin_regression.sql in the SAME transaction; always ROLLBACK.
reset role;
delete from public.refund_requests where payment_id=pg_temp.fixture_id('payment_paid');
update public.payments set fpx_transaction_ref='pi_refundfixture',payment_status='Success' where payment_id=pg_temp.fixture_id('payment_paid');
set local role authenticated;
select pg_temp.login_as('super_auth');
select public.admin_mutate('refund_request',pg_temp.fixture_id('payment_paid'),public.admin_detail('bookings',pg_temp.fixture_id('booking_paid'))->'payment'->>'version','{"amount":40,"reason":"Refund lifecycle test request"}');
reset role;
insert into admin_regression_ids select 'refund_first',refund_id from public.refund_requests where payment_id=pg_temp.fixture_id('payment_paid');
set local role authenticated;
select pg_temp.login_as('staff_auth');
select pg_temp.test_error('staff cannot process refunds','select public.admin_prepare_refund(pg_temp.fixture_id(''refund_first''))','42501','Super Admin');
select pg_temp.login_as('super_auth','aal1');
select pg_temp.test_error('refund processing requires MFA','select public.admin_prepare_refund(pg_temp.fixture_id(''refund_first''))','42501');
select pg_temp.login_as('customer_auth');
select pg_temp.test_error('customer cannot process refunds','select public.admin_prepare_refund(pg_temp.fixture_id(''refund_first''))','42501');
select pg_temp.test_error('customer cannot forge refund confirmation','select public.gateway_record_refund(pg_temp.fixture_id(''refund_first''),''re_fixture'',''pi_refundfixture'',4000,''myr'',''succeeded'')','42501');
select pg_temp.login_as('super_auth');
select pg_temp.test_assert('refund quote is trusted and processing',public.admin_prepare_refund(pg_temp.fixture_id('refund_first'))->>'amount_sen'='4000');
select pg_temp.test_assert('prepare is retryable',public.admin_prepare_refund(pg_temp.fixture_id('refund_first'))->>'status'='Processing');
select pg_temp.test_assert('booking detail reserves partial refund',public.admin_detail('bookings',pg_temp.fixture_id('booking_paid'))->'payment'->>'remaining'='60.00');
reset role;
select pg_temp.test_error('gateway amount mismatch rejected','select public.gateway_record_refund(pg_temp.fixture_id(''refund_first''),''re_fixture'',''pi_refundfixture'',5000,''myr'',''succeeded'')','P0001','does not match');
select pg_temp.test_error('gateway reference mismatch rejected','select public.gateway_record_refund(pg_temp.fixture_id(''refund_first''),''re_fixture'',''pi_other'',4000,''myr'',''succeeded'')','P0001','does not match');
select public.gateway_record_refund(pg_temp.fixture_id('refund_first'),'re_fixture','pi_refundfixture',4000,'myr','pending');
select pg_temp.test_assert('pending does not claim a refund',(select payment_status='Success' from public.payments where payment_id=pg_temp.fixture_id('payment_paid')));
select public.gateway_record_refund(pg_temp.fixture_id('refund_first'),'re_fixture','pi_refundfixture',4000,'myr','succeeded');
select public.gateway_record_refund(pg_temp.fixture_id('refund_first'),'re_fixture','pi_refundfixture',4000,'myr','succeeded');
select pg_temp.test_assert('duplicate confirmation has one audit event',(select count(*)=1 from public.audit_logs where target_id=pg_temp.fixture_id('refund_first') and action='refund_gateway_update' and new_values->>'status'='Succeeded'));
select public.gateway_record_refund(pg_temp.fixture_id('refund_first'),'re_fixture','pi_refundfixture',4000,'myr','pending');
select pg_temp.test_assert('late pending cannot reverse success',(select status='Succeeded' from public.refund_requests where refund_id=pg_temp.fixture_id('refund_first')));
select pg_temp.test_assert('partial refund preserves collected status',(select payment_status='Success' from public.payments where payment_id=pg_temp.fixture_id('payment_paid')));
set local role authenticated;
select pg_temp.login_as('super_auth');
select pg_temp.test_assert('analytics records confirmed refunds', (public.admin_analytics((now() at time zone 'Asia/Kuala_Lumpur')::date,(now() at time zone 'Asia/Kuala_Lumpur')::date,null,null,pg_temp.fixture_id('provider_profile'))->>'refunds_succeeded')::numeric=40);
select pg_temp.test_assert('analytics chart includes refunded amount', (public.admin_analytics((now() at time zone 'Asia/Kuala_Lumpur')::date,(now() at time zone 'Asia/Kuala_Lumpur')::date,null,null,pg_temp.fixture_id('provider_profile'))->'daily'->0->>'refunded')::numeric=40);
select public.admin_mutate('refund_request',pg_temp.fixture_id('payment_paid'),public.admin_detail('bookings',pg_temp.fixture_id('booking_paid'))->'payment'->>'version','{"amount":60,"reason":"Refund remaining paid amount"}');
reset role;
insert into admin_regression_ids select 'refund_second',refund_id from public.refund_requests where payment_id=pg_temp.fixture_id('payment_paid') and status='Requested';
set local role authenticated;
select public.admin_prepare_refund(pg_temp.fixture_id('refund_second'));
reset role;
update public.bookings set booking_status='Confirmed' where booking_id=pg_temp.fixture_id('booking_paid');
select public.gateway_record_refund(pg_temp.fixture_id('refund_second'),'re_second','pi_refundfixture',6000,'myr','succeeded');
select pg_temp.test_assert('full cumulative refund marks payment refunded',(select payment_status='Refunded' from public.payments where payment_id=pg_temp.fixture_id('payment_paid')));
select pg_temp.test_assert('full refund cancels unfinished booking',(select booking_status='Cancelled' from public.bookings where booking_id=pg_temp.fixture_id('booking_paid')));
set local role authenticated;
select pg_temp.login_as('super_auth');
select pg_temp.test_error('fully refunded payment cannot be refunded again','select public.admin_mutate(''refund_request'',pg_temp.fixture_id(''payment_paid''),public.admin_detail(''bookings'',pg_temp.fixture_id(''booking_paid''))->''payment''->>''version'',''{"amount":1,"reason":"Duplicate fully refunded payment"}''::jsonb)','P0001','successful payments');
reset role;
update public.users set is_active=false where user_id=pg_temp.fixture_id('customer_user');
set local role authenticated;
select pg_temp.login_as('customer_auth');
select pg_temp.test_assert('suspended owner sees refund in support',exists(select 1 from jsonb_array_elements(public.customer_support_requests()) d,jsonb_array_elements(d->'refunds') r where r->>'refund_id'=pg_temp.fixture_id('refund_second')::text and r->>'status'='Succeeded'));
reset role;
update public.booking_disputes set opened_by=pg_temp.fixture_id('super_user'),description='SECRET INTERNAL admin description',resolution='SECRET INTERNAL response' where dispute_id=(select dispute_id from public.refund_requests where refund_id=pg_temp.fixture_id('refund_second'));
set local role authenticated;
select pg_temp.test_assert('refund-only support view hides internal admin text',position('SECRET INTERNAL' in public.customer_support_requests()::text)=0);
select pg_temp.test_assert('refund-only support still exposes owned refund',position('re_second' in public.customer_support_requests()::text)>0);
select pg_temp.login_as('provider_auth');
select pg_temp.test_error('noncustomer cannot read customer refund support','select public.customer_support_requests()','42501');
reset role;
-- Bank returns can change a refund to failed after initial confirmation.
select public.gateway_record_refund(pg_temp.fixture_id('refund_second'),'re_second','pi_refundfixture',6000,'myr','failed');
select pg_temp.test_assert('bank return restores actual collected balance',(select payment_status='Success' from public.payments where payment_id=pg_temp.fixture_id('payment_paid')));
select pg_temp.test_assert('failed refund has no completion timestamp',(select completed_at is null from public.refund_requests where refund_id=pg_temp.fixture_id('refund_second')));
set local role authenticated;
select pg_temp.login_as('super_auth');
select public.admin_mutate('refund_request',pg_temp.fixture_id('payment_paid'),public.admin_detail('bookings',pg_temp.fixture_id('booking_paid'))->'payment'->>'version','{"amount":60,"reason":"Retry a definitively failed refund"}');
reset role;
insert into admin_regression_ids select 'refund_rejected',refund_id from public.refund_requests where payment_id=pg_temp.fixture_id('payment_paid') and status='Requested';
set local role authenticated;
select public.admin_prepare_refund(pg_temp.fixture_id('refund_rejected'));
reset role;
select public.gateway_reject_refund(pg_temp.fixture_id('refund_rejected'));
select pg_temp.test_assert('definitive rejection closes failed refund',(select status='Failed' from public.refund_requests where refund_id=pg_temp.fixture_id('refund_rejected')));
select public.gateway_reject_refund(pg_temp.fixture_id('refund_first'));
select pg_temp.test_assert('rejection cannot reverse accepted refund',(select status='Succeeded' from public.refund_requests where refund_id=pg_temp.fixture_id('refund_first')));
select jsonb_build_object('passed',count(*)) as refund_and_admin_regression from admin_regression_results;
